INSERT INTO `courses` (`course_id`, `category_id`, `title`, `summary`, `learning_goal`, `level`, `thumbnail_file_id`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES (2,4,'신입 직장인을 위한 엑셀 함수 기초','합계, 개수, 조건 판단, 값 찾기처럼 매일 쓰는 엑셀 함수를 숏폼으로 배웁니다.','조건별 합계와 개수, 조건 판단, 다른 표 값 찾기를 업무 표에 적용할 수 있다','BASIC',4,'PUBLISHED',1,'2026-11-03 21:26:04','2026-11-03 21:26:02','2026-11-03 21:26:04');
INSERT INTO `courses` (`course_id`, `category_id`, `title`, `summary`, `learning_goal`, `level`, `thumbnail_file_id`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES (3,4,'데이터 정리와 보고서 실무','흩어진 데이터를 정리하고 보고서로 요약하는 방법을 배웁니다.','중복과 형식을 정리하고 피벗 테이블과 서식으로 보고서를 만들 수 있다','BASIC',20,'PUBLISHED',1,'2026-11-03 21:26:06','2026-11-03 21:26:04','2026-11-03 21:26:06');
INSERT INTO `courses` (`course_id`, `category_id`, `title`, `summary`, `learning_goal`, `level`, `thumbnail_file_id`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES (4,4,'엑셀 오류 해결과 날짜 계산','자주 만나는 오류 메시지와 날짜 계산을 빠르게 해결합니다.','오류 메시지의 원인을 알고 근무일수와 날짜 간격을 계산할 수 있다','INTRO',35,'PUBLISHED',1,'2026-11-03 21:26:07','2026-11-03 21:26:06','2026-11-03 21:26:07');
INSERT INTO `contents` (`content_id`, `course_id`, `title`, `learning_goal`, `work_use`, `video_file_id`, `thumbnail_file_id`, `duration_sec`, `aspect_ratio`, `sort_order`, `version`, `status`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES (2,2,'SUMIF 함수로 조건별 합계 구하기','매출표에서 영업팀 매출만 따로 더하고 싶을 때가 있죠.','',5,6,88,NULL,1,1,'PUBLISHED',1,'2026-11-03 21:26:02','2026-11-03 21:26:02','2026-11-03 21:26:02');
