INSERT INTO `quizzes` (`quiz_id`, `content_id`, `question`, `explanation`, `sort_order`, `created_at`, `updated_at`) VALUES (2,2,'SUMIF 함수의 세 번째 인수에는 무엇을 넣나요?','세 번째 인수는 실제로 더할 범위입니다. 예시에서는 매출 금액이 있는 D열을 지정합니다.',1,'2026-11-03 21:26:02','2026-11-03 21:26:02');
INSERT INTO `quizzes` (`quiz_id`, `content_id`, `question`, `explanation`, `sort_order`, `created_at`, `updated_at`) VALUES (3,3,'SUMIFS 함수에서 맨 앞에 쓰는 인수는 무엇인가요?','SUMIFS는 SUMIF와 순서가 달라서 더할 범위를 맨 앞에 먼저 씁니다.',1,'2026-11-03 21:26:02','2026-11-03 21:26:02');
INSERT INTO `quizzes` (`quiz_id`, `content_id`, `question`, `explanation`, `sort_order`, `created_at`, `updated_at`) VALUES (4,4,'COUNTIF로 80점 이상인 사람 수를 셀 때 조건은 어떻게 쓰나요?','숫자 조건은 비교 기호와 숫자를 함께 큰따옴표로 묶어 \">=80\"처럼 씁니다.',1,'2026-11-03 21:26:03','2026-11-03 21:26:03');
INSERT INTO `quizzes` (`quiz_id`, `content_id`, `question`, `explanation`, `sort_order`, `created_at`, `updated_at`) VALUES (5,5,'IF 함수에서 결과로 \'달성\' 같은 글자를 쓸 때 주의할 점은?','IF의 결과로 글자를 쓸 때는 반드시 \"달성\"처럼 큰따옴표로 묶어야 합니다.',1,'2026-11-03 21:26:03','2026-11-03 21:26:03');
INSERT INTO `quizzes` (`quiz_id`, `content_id`, `question`, `explanation`, `sort_order`, `created_at`, `updated_at`) VALUES (6,6,'VLOOKUP에서 정확히 일치하는 값만 찾으려면 마지막 인수에 무엇을 넣나요?','마지막 인수에 FALSE를 넣어야 정확히 일치하는 값만 찾습니다.',1,'2026-11-03 21:26:04','2026-11-03 21:26:04');
INSERT INTO `quizzes` (`quiz_id`, `content_id`, `question`, `explanation`, `sort_order`, `created_at`, `updated_at`) VALUES (7,7,'원본 데이터를 고친 뒤 피벗 테이블에 반영하려면 어떻게 하나요?','원본이 바뀌면 피벗 테이블에서 마우스 오른쪽 버튼을 눌러 새로 고침을 해야 반영됩니다.',1,'2026-11-03 21:26:04','2026-11-03 21:26:04');
INSERT INTO `quizzes` (`quiz_id`, `content_id`, `question`, `explanation`, `sort_order`, `created_at`, `updated_at`) VALUES (8,8,'이름과 전화번호 열을 함께 선택해 중복된 항목 제거를 하면 어떻게 되나요?','여러 열을 함께 선택하면 선택한 모든 열의 값이 같은 행만 중복으로 봅니다.',1,'2026-11-03 21:26:05','2026-11-03 21:26:05');
INSERT INTO `quizzes` (`quiz_id`, `content_id`, `question`, `explanation`, `sort_order`, `created_at`, `updated_at`) VALUES (9,9,'텍스트 나누기에서 사번 앞자리 0이 사라지지 않게 하려면 어떻게 하나요?','앞자리 0이 사라지면 안 되는 열은 텍스트 나누기 마지막 단계에서 텍스트 형식으로 지정합니다.',1,'2026-11-03 21:26:05','2026-11-03 21:26:05');
INSERT INTO `quizzes` (`quiz_id`, `content_id`, `question`, `explanation`, `sort_order`, `created_at`, `updated_at`) VALUES (10,10,'목표에 못 미친 사람의 행 전체를 칠하려면 어떤 규칙을 쓰나요?','행 전체를 칠하려면 새 규칙에서 수식을 사용하여 서식을 지정할 셀 결정을 고르고, 달러 기호로 열을 고정합니다.',1,'2026-11-03 21:26:05','2026-11-03 21:26:05');
INSERT INTO `quizzes` (`quiz_id`, `content_id`, `question`, `explanation`, `sort_order`, `created_at`, `updated_at`) VALUES (11,11,'첫 행과 이름이 있는 첫 열을 함께 고정하려면 어떤 셀을 선택하고 틀 고정을 누르나요?','고정할 위치 바로 오른쪽 아래 셀을 선택하고 틀 고정을 누르면 그 위쪽 행과 왼쪽 열이 함께 고정됩니다.',1,'2026-11-03 21:26:06','2026-11-03 21:26:06');
INSERT INTO `quizzes` (`quiz_id`, `content_id`, `question`, `explanation`, `sort_order`, `created_at`, `updated_at`) VALUES (12,12,'시작일과 종료일 사이에서 주말을 뺀 근무일수를 구하는 함수는?','NETWORKDAYS에 시작일과 종료일을 넣으면 주말을 뺀 근무일수가 나오고, 세 번째 인수로 공휴일도 뺄 수 있습니다.',1,'2026-11-03 21:26:06','2026-11-03 21:26:06');
INSERT INTO `quizzes` (`quiz_id`, `content_id`, `question`, `explanation`, `sort_order`, `created_at`, `updated_at`) VALUES (13,13,'수식에 #N/A가 나타나는 원인으로 알맞은 것은?','#N/A는 찾는 값이 없다는 뜻으로, VLOOKUP에서 찾는 값이 목록에 없을 때 자주 나옵니다.',1,'2026-11-03 21:26:07','2026-11-03 21:26:07');
