INSERT INTO `quiz_options` (`option_id`, `quiz_id`, `option_no`, `option_text`, `is_correct`, `feedback`, `feedback_source`, `rewatch_sec`, `created_at`, `updated_at`) VALUES (52,13,4,'숫자 자리에 글자가 들어갔다',0,'숫자 자리에 글자가 들어가면 #VALUE! 오류가 나요.','ADMIN',26,'2026-11-03 21:26:07','2026-11-03 21:26:07');
INSERT INTO `practices` (`practice_id`, `content_id`, `title`, `instruction`, `example_file_id`, `expected_result`, `result_type`, `tolerance`, `required_function`, `answer_formula`, `created_at`, `updated_at`) VALUES (2,2,'부서별 매출 합계 구하기','예제 파일에서 SUMIF를 써서 영업팀 매출 합계를 구해 보세요. 부서는 B열, 매출은 D열입니다.',7,'600000','NUMBER',0.0000,'SUMIF','=SUMIF(B2:B11,\"영업팀\",D2:D11)','2026-11-03 21:26:02','2026-11-03 21:26:02');
INSERT INTO `practices` (`practice_id`, `content_id`, `title`, `instruction`, `example_file_id`, `expected_result`, `result_type`, `tolerance`, `required_function`, `answer_formula`, `created_at`, `updated_at`) VALUES (3,3,'영업팀 3월 매출 합계','SUMIFS로 영업팀이면서 3월(3월 1일~3월 31일)에 판매한 매출만 더해 보세요.',10,'270000','NUMBER',0.0000,'SUMIFS','=SUMIFS(D2:D11,B2:B11,\"영업팀\",A2:A11,\">=2026-03-01\",A2:A11,\"<=2026-03-31\")','2026-11-03 21:26:02','2026-11-03 21:26:02');
INSERT INTO `practices` (`practice_id`, `content_id`, `title`, `instruction`, `example_file_id`, `expected_result`, `result_type`, `tolerance`, `required_function`, `answer_formula`, `created_at`, `updated_at`) VALUES (4,4,'80점 이상인 사람 수 세기','COUNTIF로 점수가 80점 이상인 사람 수를 세어 보세요. 점수는 C열입니다.',13,'5','NUMBER',0.0000,'COUNTIF','=COUNTIF(C2:C9,\">=80\")','2026-11-03 21:26:03','2026-11-03 21:26:03');
INSERT INTO `practices` (`practice_id`, `content_id`, `title`, `instruction`, `example_file_id`, `expected_result`, `result_type`, `tolerance`, `required_function`, `answer_formula`, `created_at`, `updated_at`) VALUES (5,5,'목표 달성 여부 표시하기','D열에 IF로 매출이 목표보다 크거나 같으면 \"달성\", 아니면 \"미달\"을 표시하고, 미달인 사람 수를 구해 보세요.',16,'3','NUMBER',0.0000,'IF','=IF(B2>=C2,\"달성\",\"미달\")','2026-11-03 21:26:03','2026-11-03 21:26:03');
INSERT INTO `practices` (`practice_id`, `content_id`, `title`, `instruction`, `example_file_id`, `expected_result`, `result_type`, `tolerance`, `required_function`, `answer_formula`, `created_at`, `updated_at`) VALUES (6,6,'사번으로 이름 찾기','직원 목록에서 VLOOKUP을 써서 사번 1007의 이름을 찾아보세요. 마지막 인수는 FALSE로 넣으세요.',19,'오세린','TEXT',0.0000,'VLOOKUP','=VLOOKUP(1007,A2:C9,2,FALSE)','2026-11-03 21:26:04','2026-11-03 21:26:04');
INSERT INTO `practices` (`practice_id`, `content_id`, `title`, `instruction`, `example_file_id`, `expected_result`, `result_type`, `tolerance`, `required_function`, `answer_formula`, `created_at`, `updated_at`) VALUES (7,7,'피벗 테이블로 월별·부서별 합계 보기','예제 파일로 피벗 테이블을 만들고 날짜를 월로 그룹화해 3월 마케팅팀 매출 합계를 확인해 보세요.',23,'175000','NUMBER',0.0000,NULL,NULL,'2026-11-03 21:26:04','2026-11-03 21:26:04');
INSERT INTO `practices` (`practice_id`, `content_id`, `title`, `instruction`, `example_file_id`, `expected_result`, `result_type`, `tolerance`, `required_function`, `answer_formula`, `created_at`, `updated_at`) VALUES (8,8,'중복 고객 정리하기','이름과 전화번호 열을 함께 선택해 중복된 항목 제거를 한 뒤, 남은 고객이 몇 명인지 확인해 보세요.',26,'5','NUMBER',0.0000,NULL,NULL,'2026-11-03 21:26:05','2026-11-03 21:26:05');
INSERT INTO `practices` (`practice_id`, `content_id`, `title`, `instruction`, `example_file_id`, `expected_result`, `result_type`, `tolerance`, `required_function`, `answer_formula`, `created_at`, `updated_at`) VALUES (9,9,'한 칸에 붙은 이름과 부서 나누기','B열을 슬래시(/) 기준으로 텍스트 나누기 해보세요. 사번 0103 직원의 부서는 무엇인가요?',29,'재무팀','TEXT',0.0000,NULL,NULL,'2026-11-03 21:26:05','2026-11-03 21:26:05');
INSERT INTO `practices` (`practice_id`, `content_id`, `title`, `instruction`, `example_file_id`, `expected_result`, `result_type`, `tolerance`, `required_function`, `answer_formula`, `created_at`, `updated_at`) VALUES (10,10,'목표 미달 칸 강조하기','조건부 서식으로 매출이 목표보다 작은 행 전체를 빨간색으로 칠해 보세요. 칠해진 사람은 몇 명인가요?',32,'3','NUMBER',0.0000,NULL,NULL,'2026-11-03 21:26:05','2026-11-03 21:26:05');
INSERT INTO `practices` (`practice_id`, `content_id`, `title`, `instruction`, `example_file_id`, `expected_result`, `result_type`, `tolerance`, `required_function`, `answer_formula`, `created_at`, `updated_at`) VALUES (11,12,'프로젝트 근무일수 구하기','NETWORKDAYS로 2026-11-02부터 2026-11-27까지 주말을 뺀 근무일수를 구해 보세요. 이 기간에는 공휴일이 없습니다.',38,'20','NUMBER',0.0000,'NETWORKDAYS','=NETWORKDAYS(A2,B2)','2026-11-03 21:26:06','2026-11-03 21:26:06');
INSERT INTO `practices` (`practice_id`, `content_id`, `title`, `instruction`, `example_file_id`, `expected_result`, `result_type`, `tolerance`, `required_function`, `answer_formula`, `created_at`, `updated_at`) VALUES (12,13,'나누기 오류를 0으로 바꾸기','D열에 매출을 목표로 나눈 달성률을 구하면 목표가 0인 지점에서 #DIV/0!가 나옵니다. IFERROR로 오류를 0으로 바꾼 뒤 D열 합계를 소수 둘째 자리까지 구해 보세요.',41,'2.85','NUMBER',0.0100,'IFERROR','=IFERROR(B2/C2,0)','2026-11-03 21:26:07','2026-11-03 21:26:07');
